// File-type icons for the sample tree, embedded as data URIs.
// Generated from assets/identity/*-16.svg — do not edit by hand.
/* eslint-disable */
const gad = "data:image/svg+xml;base64,";
const gadt = "data:image/svg+xml;base64,";
const gadx = "data:image/svg+xml;base64,";
const gadTest = "data:image/svg+xml;base64,";

// iconFor returns the data-URI icon for a sample path, chosen by extension
// (*_test.gad gets the test-badge variant).
export function iconFor(path: string): string {
  if (path.endsWith(".gadx")) return gadx;
  if (path.endsWith(".gadt")) return gadt;
  if (path.endsWith("_test.gad")) return gadTest;
  return gad;
}
